const rows = $input.all().map(i => i.json);
const now = new Date();
const weekAgo = new Date(now - 7*24*60*60*1000);

const thisWeek = rows.filter(r => {
  try { return new Date(r.Date) >= weekAgo; } catch { return true; }
});

const leads = thisWeek.filter(r => r.Type === 'Lead').length;
const demos = thisWeek.filter(r => r.Type === 'Demo').length;
const proposals = thisWeek.filter(r => r.Type === 'Proposal').length;
const closedDeals = thisWeek.filter(r => r.Type === 'Deal' && r.Status === 'Closed');
const lostDeals = thisWeek.filter(r => r.Type === 'Deal' && r.Status === 'Lost');

const revenue = closedDeals.reduce((s, r) => s + (parseFloat(r.DealValue) || 0), 0);
const avgDeal = closedDeals.length ? (revenue / closedDeals.length).toFixed(0) : 0;
const convRate = (leads + demos) ? ((closedDeals.length / (leads + demos)) * 100).toFixed(1) : 0;

const topRep = Object.entries(
  closedDeals.reduce((acc, r) => { acc[r.SalesRep] = (acc[r.SalesRep]||0) + (parseFloat(r.DealValue)||0); return acc; }, {})
).sort((a,b) => b[1]-a[1])[0];

const weekStr = now.toISOString().slice(0,10);
const dataSnippet = thisWeek.slice(0,20).map(r => 
  `${r.Date} | ${r.Type} | ${r.Status} | $${r.DealValue || 0} | ${r.SalesRep} | ${r.Client}`
).join('\n');

return [{json: {
  week_ending: weekStr,
  total_leads: leads,
  total_demos: demos,
  total_proposals: proposals,
  closed_deals: closedDeals.length,
  lost_deals: lostDeals.length,
  total_revenue: revenue,
  avg_deal_size: avgDeal,
  conversion_rate: convRate,
  top_rep: topRep ? `${topRep[0]} ($${topRep[1].toLocaleString()})` : 'N/A',
  data_snippet: dataSnippet
}}];

