const narrative = $input.first().json.content?.[0]?.text ?? 'No narrative generated.';
const m = $('Calculate KPI Metrics').first().json;

const html = `<!DOCTYPE html>
<html><head><meta charset="utf-8">
<style>
  body{font-family:Arial,sans-serif;background:#f5f5f5;margin:0;padding:0}
  .container{max-width:640px;margin:24px auto;background:#fff;border-radius:8px;overflow:hidden;box-shadow:0 2px 8px rgba(0,0,0,0.1)}
  .header{background:linear-gradient(135deg,#4f46e5,#7c3aed);color:#fff;padding:32px;text-align:center}
  .header h1{margin:0;font-size:24px}
  .header p{margin:8px 0 0;opacity:0.85;font-size:14px}
  .kpi-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:1px;background:#e5e7eb}
  .kpi{background:#fff;padding:20px;text-align:center}
  .kpi .val{font-size:28px;font-weight:700;color:#4f46e5}
  .kpi .lbl{font-size:11px;color:#6b7280;margin-top:4px;text-transform:uppercase;letter-spacing:.5px}
  .section{padding:24px 32px}
  .section h2{font-size:16px;color:#374151;border-bottom:2px solid #4f46e5;padding-bottom:8px}
  .narrative{color:#374151;line-height:1.7;font-size:14px}
  .footer{background:#f9fafb;padding:16px 32px;font-size:12px;color:#9ca3af;text-align:center;border-top:1px solid #e5e7eb}
</style></head><body>
<div class="container">
  <div class="header">
    <h1>Weekly Performance Report</h1>
    <p>Week ending ${m.week_ending}</p>
  </div>
  <div class="kpi-grid">
    <div class="kpi"><div class="val">${m.total_leads}</div><div class="lbl">New Leads</div></div>
    <div class="kpi"><div class="val">${m.total_demos}</div><div class="lbl">Demos</div></div>
    <div class="kpi"><div class="val">${m.closed_deals}</div><div class="lbl">Deals Closed</div></div>
    <div class="kpi"><div class="val">$${Number(m.total_revenue).toLocaleString()}</div><div class="lbl">Revenue</div></div>
    <div class="kpi"><div class="val">$${Number(m.avg_deal_size).toLocaleString()}</div><div class="lbl">Avg Deal</div></div>
    <div class="kpi"><div class="val">${m.conversion_rate}%</div><div class="lbl">Conv. Rate</div></div>
  </div>
  <div class="section">
    <h2>Executive Narrative</h2>
    <div class="narrative">${narrative.replace(/\n/g,'<br>')}</div>
  </div>
  <div class="section">
    <h2>Top Performer</h2>
    <p style="color:#374151;font-size:14px">:trophy: ${m.top_rep}</p>
  </div>
  <div class="footer">Generated by n8n + Claude AI &middot; ${m.week_ending}</div>
</div></body></html>`;

return [{json: {...$('Calculate KPI Metrics').first().json, html_report: html}}];
